const deskPositions=[[18,65],[31,65],[44,65],[57,65],[18,82],[31,82],[44,82],[57,82],[25,73],[51,73]];
const researchPositions=[[70,18],[85,18],[70,33],[85,33]];
const reviewPositions=[[32,22],[47,22],[32,33],[47,33]];
const verifyPositions=[[75,68],[87,68],[75,82],[87,82]];
const breakPositions=[[61,37],[64,37],[61,41],[65,41]];
function nameHash(name){let h=0;for(const ch of name)h=(h*31+ch.charCodeAt(0))>>>0;return h}
function avatarPalette(a,director=false){const h=nameHash(a.name||'agent');const skins=['#d9a478','#b97b56','#e3b88e','#8f5e45','#c98f68'];const hairs=['#261b20','#5a3c2e','#2e2a32','#7a5034','#b79a6a'];return {skin:skins[h%skins.length],hair:hairs[(h>>2)%hairs.length],shirt:director?'#754f70':capabilityColor(a),accent:['#d9b56d','#7ba0b3','#9e7ba8','#7f9e79'][h%4]}}
function activityFor(name){if(name==='Office Director')return phaseActivity(runtimePhaseFor(name))||'coordinating';const ctl=state.data?.agent_controls?.[name]?.state;if(ctl==='paused'||ctl==='halted')return 'blocked';const live=phaseActivity(runtimePhaseFor(name));if(live)return live;const row=taskFor(name);if(!row)return 'idle';return ({NEEDS_RESEARCH:'researching',EVIDENCE_REQUIRED:'researching',HYPOTHESIS:'researching',ASSIGNED:'coding',IMPLEMENTATION:'coding',EXPERIMENT:'experimenting',REVIEW:'reviewing',NEEDS_SPECIALIST:'reviewing',ESCALATED:'reviewing',TEST:'verifying',VERIFY:'verifying',PASS:'idle',FAILED:'blocked',BLOCKED:'blocked',REGRESSION_FAILED:'blocked'}[row.state]||'coding')}
function destinationFor(a,index=0,director=false){if(director)return {x:13,y:23,zone:'director'};const activity=activityFor(a.name);let bank=deskPositions,zone='lab';if(activity==='researching'){bank=researchPositions;zone='research'}else if(activity==='reviewing'){bank=reviewPositions;zone='meeting'}else if(activity==='verifying'){bank=verifyPositions;zone='review'}else if(activity==='idle'){bank=breakPositions;zone='break'}else if(activity==='blocked'){bank=[[23,35],[26,35],[54,35],[57,35]];zone='attention'}const [x,y]=bank[index%bank.length];return {x,y,zone}}
function toolMark(activity){return ({researching:'?',coding:'<>',experimenting:'LAB',reviewing:'DOC',verifying:'✓',blocked:'!',idle:'·',coordinating:'DIR'}[activity]||'<>')}
