function renderHandoffs(){const known=new Set(['Office Director',...(state.data?.status?.agents||[]).map(a=>a.name)]);return (state.data?.messages||[]).slice(-12).filter(m=>known.has(m.sender)&&known.has(m.recipient)&&m.sender!==m.recipient).slice(-3).map((m,i)=>{const a=floorPosition(m.sender),b=floorPosition(m.recipient);if(!a||!b)return'';const dx=b.x-a.x,dy=b.y-a.y,len=Math.sqrt(dx*dx+dy*dy),ang=Math.atan2(dy,dx)*180/Math.PI;return `<span class="handoff-line handoff-${i}" style="left:${a.x}%;top:${a.y}%;width:${len}%;transform:rotate(${ang}deg)" title="${esc(m.sender)} → ${esc(m.recipient)}"><i class="handoff-pulse"></i></span>`}).join('')}
function renderFloorSummary(){const el=$('#floor-activity-summary');if(!el)return;const agents=state.data?.status?.agents||[];const counts={coding:0,researching:0,experimenting:0,reviewing:0,verifying:0,blocked:0,idle:0};for(const a of agents){const k=activityFor(a.name);if(k in counts)counts[k]++}const active=Object.entries(counts).filter(([k,v])=>v&&k!=='idle').map(([k,v])=>`${v} ${k}`).join(' · ');el.textContent=active||`${counts.idle} idle`;}
function renderFloor(){const stage=$('#office-stage');if(!stage||!state.data?.status)return;const agents=state.data.status.agents||[];const renderer=ensureFloorRenderer();if(renderer){stage.classList.add('canvas-living');const rows=[{name:'Office Director',role:'orchestrator',phase:runtimePhaseFor('Office Director')||'PLANNING',displayName:'Office Director',bubble:runtimeBubble('Office Director')},...agents.map(a=>({name:a.name,role:(a.capabilities||[]).join(' '),phase:runtimePhaseFor(a.name)||({coding:'CODING',researching:'RESEARCHING',experimenting:'EXPERIMENTING',reviewing:'REVIEWING',verifying:'VERIFYING',blocked:'BLOCKED',idle:'IDLE'}[activityFor(a.name)]||'IDLE'),displayName:a.name,bubble:runtimeBubble(a.name)}))];const handoffs=effectiveRuntimeEvents().filter(e=>e.kind==='message.sent').slice(-4).map(e=>({sender:e.payload?.sender,recipient:e.payload?.recipient,event:e}));renderer.update({agents:rows,handoffs,models:state.modelRuntime?.models||{},selected:state.selected,summary:$('#floor-activity-summary')?.textContent||''});const summary=rows.map(a=>`${a.name}: ${a.phase}`).join('; ');$('#floor-accessible-summary').textContent=summary;renderFloorSummary();return}const director={name:'Office Director',capabilities:['orchestration']};const old={...state.floorPositions};stage.innerHTML=roomScaffold()+renderHandoffs()+station(director,0,true)+agents.map((a,i)=>station(a,i,false)).join('');stage.querySelectorAll('[data-agent]').forEach(el=>{const name=el.dataset.agent;const dest={x:Number(el.dataset.destX),y:Number(el.dataset.destY)};const previous=old[name];if(previous&&(previous.x!==dest.x||previous.y!==dest.y)){el.style.left=`${previous.x}%`;el.style.top=`${previous.y}%`;requestAnimationFrame(()=>requestAnimationFrame(()=>{el.style.left=`${dest.x}%`;el.style.top=`${dest.y}%`}))}state.floorPositions[name]=dest;el.onclick=()=>selectAgent(name)});renderFloorSummary()}
function rosterCard(a,director=false){const name=a.name;return `<button class="roster-card ${state.selected===name?'selected':''}" data-roster-agent="${esc(name)}"><span class="roster-sprite">${spriteMarkup(a,director,true)}</span><span class="roster-copy"><strong>${esc(director?'Office Director':name)}</strong><small>${esc(director?'orchestrator':(a.capabilities||[]).join(' · '))}</small><small>${esc(bubbleText(name))}</small></span><span class="roster-state">${esc(stateLabel(name))}</span></button>`}
function renderRoster(){const roster=$('#agent-roster');if(!roster)return;const agents=state.data?.status?.agents||[];roster.innerHTML=rosterCard({name:'Office Director'},true)+agents.map(a=>rosterCard(a)).join('')+`<button id="add-agent-card" class="add-agent-card">＋ Add Agent</button>`;roster.querySelectorAll('[data-roster-agent]').forEach(el=>el.onclick=()=>selectAgent(el.dataset.rosterAgent));$('#add-agent-card').onclick=()=>show('add-agent-modal')}
async function selectAgent(name){state.selected=name;state.tab='ACTIVITY';renderFloor();renderRoster();await loadSelected(false)}
async function pullSelectedTerminal(quiet=true){if(!state.data?.initialized||!state.selected)return;const name=state.selected;const cursor=state.terminalCursorByAgent[name];try{const q=cursor?`?after=${encodeURIComponent(cursor)}&limit=300`:'?limit=300';const payload=await api(`/api/agents/${encodeURIComponent(name)}/terminal${q}`);const prior=state.terminalCacheByAgent[name]||[];if(payload.entries?.length){state.terminalCacheByAgent[name]=[...prior,...payload.entries].slice(-700);state.terminalCursorByAgent[name]=payload.cursor}else if(!state.terminalCacheByAgent[name])state.terminalCacheByAgent[name]=[];if(state.tab==='TERMINAL')renderInspectorPanel()}catch(err){if(!quiet)toast(err.message,true)}}
async function loadSelected(quiet=false){if(!state.data?.initialized)return;try{state.detail=await api('/api/agents/'+encodeURIComponent(state.selected));await pullSelectedTerminal(true);renderInspector()}catch(e){if(!quiet)toast(e.message,true)}}
function renderInspector(){const d=state.detail;if(!d)return;const a=d.agent;const isDirector=a.name==='Office Director';const task=d.task?.task;const taskState=d.task?.state;const ctl=d.control?.state||'running';const tier=a.model_tier||'HIGH';$('#inspector-head').innerHTML=`<span class="inspector-portrait">${spriteMarkup(a,isDirector,true)}</span><span class="inspector-id"><strong>${esc(a.name)}</strong><small>${esc(isDirector?'Office orchestration':(a.capabilities||[]).join(' · '))}${task?` · ${esc(task.task_id)}`:''}</small><small>${esc(task?.goal||a.mission||'Coordinates the project')}</small></span><span class="agent-model-pill">${esc(tier)} tier</span><span class="agent-status">${esc(ctl==='running'?(taskState||stateLabel(a.name)).toLowerCase():ctl)}</span>`;
  $('#agent-control-bar').innerHTML=isDirector?`<button data-office-control="pause">${state.data.control?.paused?'RESUME FLOOR':'PAUSE FLOOR'}</button><button class="halt" data-office-control="stop">HALT FLOOR</button>`:`${ctl==='running'?`<button data-agent-control="pause">PAUSE</button><button class="halt" data-agent-control="halt">HALT</button>`:`<button class="resume" data-agent-control="resume">RESUME</button>`}<button data-agent-open="1">OPEN DETAILS</button>`;
  $('#steer-input').placeholder=isDirector?'Give the Director an instruction…':'Steer this agent with extra context…';
  $('#inspector-tabs').innerHTML=inspectorTabs.map(t=>`<button class="inspector-tab ${state.tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('');
  $('#queue-count').textContent=`${(d.queue||[]).length} waiting`;$('#agent-queue').innerHTML=renderQueue(d.queue||[]);renderInspectorPanel();bindInspector()}
function renderQueue(rows){if(!rows.length)return `<div class="empty-panel">Queue is clear.</div>`;return rows.slice().reverse().map(m=>`<div class="queue-item"><b>${esc(m.sender)}</b><p>${esc(messageText(m))}</p></div>`).join('')}
function messageText(m){const d=m.data||{};return d.message||d.reason||d.required_outcome||Object.values(d).filter(v=>typeof v==='string').join(' · ')||m.kind}
function renderInspectorPanel(){const d=state.detail;if(!d)return;const panel=$('#inspector-panel');if(state.tab==='ACTIVITY'){const events=effectiveRuntimeEvents().filter(e=>e.agent_id===state.selected).slice(-20).reverse();const current=friendlyEvent(events[0]||latestRuntimeEvent(state.selected));panel.innerHTML=`<div class="activity-summary-card"><span class="overview-label">WHAT THEY'RE DOING</span><strong>${esc(current.title)}</strong><small>${esc(current.detail)}</small><button class="secondary-action" data-open-terminal type="button">Open terminal</button></div><div class="activity-list">${events.length?events.map(e=>{const f=friendlyEvent(e);return `<div class="activity-item"><span class="activity-time">${esc(String(e.timestamp||'').slice(11,19))}</span><span><strong>${esc(f.title)}</strong><small>${esc(f.detail)}</small></span></div>`}).join(''):'<div class="empty-panel">No observable activity yet.</div>'}</div>`;panel.querySelector('[data-open-terminal]')?.addEventListener('click',()=>{state.tab='TERMINAL';renderInspector()});return}if(state.tab==='MODEL'){const models=state.residency?.models||state.modelRuntime?.models||{};panel.innerHTML=`<div class="model-status-grid">${Object.entries(models).map(([name,row])=>`<div class="model-status-card"><strong>${esc(name)}</strong><small>${esc(row.status||row.kind||row.phase||'unknown')}</small><small>${esc(row.model||row.payload?.model||'local model')}</small></div>`).join('')||'<div class="empty-panel">No local-model lifecycle activity has been recorded yet.</div>'}</div>`;return}if(state.tab==='TERMINAL'){const entries=state.terminalCacheByAgent[state.selected]||[];const lines=d.terminal||[];panel.innerHTML=`<div class="terminal live-terminal">${entries.length?entries.map(entry=>{const cls=entry.severity==='error'?'error':entry.kind==='command.started'?'prompt':'';return `<div class="terminal-event ${cls}"><span class="terminal-meta">${esc(String(entry.timestamp||'').slice(11,19))} ${esc(entry.kind)}</span><pre>${esc(entry.text||'')}</pre>${entry.truncated?'<span class="terminal-truncated">output truncated · full evidence remains on disk</span>':''}</div>`}).join(''):lines.map(line=>`<div class="${String(line).startsWith('!')?'error':String(line).startsWith('$')?'prompt':''}">${esc(line)}</div>`).join('')||'No observable terminal activity yet.'}</div>`;return}if(state.tab==='FILES'){panel.innerHTML=(d.files||[]).length?(d.files||[]).map(f=>`<div class="file-row"><strong>${esc(f.status)}</strong><span>${esc(f.path)}</span></div>`).join(''):`<div class="empty-panel">No changed files on this floor.</div>`;return}if(state.tab==='MESSAGES'){panel.innerHTML=(d.messages||[]).length?(d.messages||[]).slice().reverse().map(m=>`<div class="message-row"><span class="row-meta">${esc(m.sender)} → ${esc(m.recipient)}<br>${esc(m.kind)}</span><span class="message-body">${esc(messageText(m))}</span></div>`).join(''):`<div class="empty-panel">No messages yet.</div>`;return}if(state.tab==='TASK'){const row=d.task;if(!row){panel.innerHTML=`<div class="empty-panel">The Director coordinates the whole floor and has no single task contract.</div>`;return}const t=row.task;panel.innerHTML=`<div class="task-detail-row"><strong>STATE</strong><span>${esc(row.state)}</span></div><div class="task-detail-row"><strong>GOAL</strong><span>${esc(t.goal)}</span></div><div class="task-detail-row"><strong>OWNER</strong><span>${esc(t.owner)}</span></div><div class="task-detail-row"><strong>RISK</strong><span>${esc(t.risk)} · ${esc(t.complexity)}</span></div><div class="task-detail-row"><strong>DEPENDENCIES</strong><span>${esc((t.dependencies||[]).join(', ')||'none')}</span></div><div class="task-detail-row"><strong>ACCEPTANCE</strong><span>${esc((t.acceptance_criteria||[]).join('\n'))}</span></div>`;return}if(state.tab==='EVIDENCE'){panel.innerHTML=(d.evidence||[]).length?(d.evidence||[]).slice().reverse().map(e=>`<div class="evidence-row"><span class="row-meta">${esc(e.run_id)}<br>${Number(e.size||0)} bytes</span><span><strong>${esc(e.name)}</strong><br><span class="row-meta">${esc(e.sha256?.slice(0,18)||'')}</span></span></div>`).join(''):`<div class="empty-panel">No task evidence captured yet.</div>`;return}if(state.tab==='TRACES'){panel.innerHTML=(d.traces||[]).length?(d.traces||[]).slice().reverse().map(e=>`<div class="trace-row"><span class="row-meta">${esc(e.created_at||'')}<br>${esc(e.task_id||'office')}</span><span><strong>${esc(e.kind)}</strong><br>${esc(traceText(e))}</span></div>`).join(''):`<div class="empty-panel">No trace events yet.</div>`}}
function traceText(e){const d=e.data||{};return d.reason||d.state||d.message||d.agent||d.objective||Object.values(d).filter(v=>typeof v==='string').slice(0,2).join(' · ')||''}
function bindInspector(){$$('#inspector-tabs [data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;renderInspector()});$$('[data-agent-control]').forEach(b=>b.onclick=()=>agentControl(b.dataset.agentControl));$$('[data-office-control]').forEach(b=>b.onclick=()=>officeControl(b.dataset.officeControl));const open=$('[data-agent-open]');if(open)open.onclick=()=>{state.tab='TRACES';renderInspector()}}

async function agentControl(action){try{const result=await api(`/api/agents/${encodeURIComponent(state.selected)}/control/${action}`,{method:'POST',body:'{}'});toast(`${state.selected}: ${result.state}`);await refresh(false)}catch(e){toast(e.message,true)}}
async function officeControl(action){try{if(action==='pause'){const endpoint=state.data.control?.paused?'/api/control/resume':'/api/control/pause';await api(endpoint,{method:'POST',body:'{}'});toast(state.data.control?.paused?'Floor resumed':'Floor paused')}else if(action==='stop'){if(!confirm('Halt the whole floor after the current safe boundary?'))return;await api('/api/control/stop',{method:'POST',body:'{}'});toast('Floor halt requested')}await refresh(false)}catch(e){toast(e.message,true)}}
$('#steer-form').onsubmit=async e=>{e.preventDefault();const message=$('#steer-input').value.trim();if(!message)return;try{if(state.selected==='Office Director'){await api('/api/objective',{method:'POST',body:json({objective:message})});toast('Director objective updated')}else{await api(`/api/agents/${encodeURIComponent(state.selected)}/steer`,{method:'POST',body:json({message})});toast(`Steered ${state.selected}`)}$('#steer-input').value='';await loadSelected()}catch(err){toast(err.message,true)}};

function renderFloorMenu(){const menu=$('#floor-menu');const floors=state.data?.floors||[];menu.innerHTML=floors.map(f=>`<button class="floor-menu-item" data-floor="${esc(f.path)}"><span><strong>${esc(f.name)}</strong><small>${esc(f.path)}</small></span>${f.current?'<em>current</em>':f.initialized?'<em>ready</em>':'<em>new</em>'}</button>`).join('')+`<button class="new-floor-button">＋ New Floor</button>`;menu.classList.remove('hidden');$('#floor-switcher').setAttribute('aria-expanded','true');menu.querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>switchFloor(b.dataset.floor));menu.querySelector('.new-floor-button').onclick=()=>{menu.classList.add('hidden');openUniversalIntake(true)}}
async function switchFloor(path){try{state.data=await api('/api/floors',{method:'POST',body:json({path})});state.selected='Office Director';state.detail=null;$('#floor-menu').classList.add('hidden');$('#floor-switcher').setAttribute('aria-expanded','false');if(!state.data.initialized)openUniversalIntake(false,path);await refresh(false)}catch(e){toast(e.message,true)}}
$('#floor-switcher').onclick=()=>{$('#floor-menu').classList.contains('hidden')?renderFloorMenu():$('#floor-menu').classList.add('hidden')};

async function loadReplayRange(){const events=state.runtimeEvents;if(!events.length)return toast('No runtime events to replay',true);const start=events[0].timestamp,end=events[events.length-1].timestamp;const payload=await api(`/api/replay?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}&limit=5000`);state.replay={...state.replay,active:true,events:payload.events||[],index:0,playing:false};renderFloor();renderReplayControls()}
function exitReplay(){if(state.replay.timer)clearInterval(state.replay.timer);state.replay={active:false,events:[],index:0,playing:false,timer:null};renderFloor();openUtility('timeline')}
function renderReplayControls(){if(!state.replay.active)return;const scrub=$('#replay-scrub');if(scrub){scrub.max=Math.max(0,state.replay.events.length-1);scrub.value=state.replay.index}const badge=$('#replay-mode');if(badge)badge.textContent=`REPLAY ${state.replay.index+1}/${state.replay.events.length}`;renderFloor()}
function replayPlayPause(){if(!state.replay.active)return;if(state.replay.playing){clearInterval(state.replay.timer);state.replay.playing=false;renderReplayControls();return}state.replay.playing=true;state.replay.timer=setInterval(()=>{if(state.replay.index>=state.replay.events.length-1){clearInterval(state.replay.timer);state.replay.playing=false;return renderReplayControls()}state.replay.index++;renderReplayControls()},450);renderReplayControls()}
function openUtility(kind){const d=state.data;$('#utility-modal').classList.remove('hidden');$('#utility-kicker').textContent='ENGINEERING OFFICE';const content=$('#utility-content');if(kind==='board'){const rows=d.status?.tasks||[];$('#utility-title').textContent='Task Board';const groups=[['ACTIVE',rows.filter(r=>!terminalStates.has(r.state))],['VERIFIED',rows.filter(r=>r.state==='PASS')],['BLOCKED',rows.filter(r=>['BLOCKED','FAILED','REGRESSION_FAILED'].includes(r.state))],['ALL',rows]];content.innerHTML=`<div class="board-columns">${groups.map(([name,list])=>`<section class="board-column"><h3>${name} · ${list.length}</h3>${list.map(taskCard).join('')||'<div class="empty-panel">None</div>'}</section>`).join('')}</div>`}else if(kind==='approvals'){const rows=(d.approvals||[]).filter(a=>a.status==='PENDING');$('#utility-title').textContent='Needs Your Approval';content.innerHTML=rows.map(a=>`<div class="approval-card"><strong>${esc(a.action)}</strong><p>${esc(a.risk_class)} risk · ${esc(a.reason)}</p><div class="approval-actions"><button class="deny" data-deny="${esc(a.approval_id)}">Deny</button><button class="approve" data-approve="${esc(a.approval_id)}">Approve</button></div></div>`).join('')||'<div class="empty-panel">Nothing is waiting for approval.</div>';content.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>decideApproval(b.dataset.approve,'approve'));content.querySelectorAll('[data-deny]').forEach(b=>b.onclick=()=>decideApproval(b.dataset.deny,'deny'))}else if(kind==='memory'){const rows=d.memory||[];$('#utility-title').textContent='Office Memory';content.innerHTML=`<input id="memory-query" class="memory-search" placeholder="Ask/search office memory…"><div id="memory-results" class="utility-grid">${memoryCards(rows)}</div>`;$('#memory-query').oninput=e=>{$('#memory-results').innerHTML=memoryCards(rows,e.target.value)}}else if(kind==='timeline'){const rows=effectiveRuntimeEvents().slice().reverse();$('#utility-title').textContent='Activity Timeline';content.innerHTML=`<div class="timeline-toolbar"><select id="timeline-filter"><option value="">All</option><option>agent</option><option>task</option><option>model</option><option>error</option><option>review</option><option>verification</option></select><button id="replay-range" type="button">${state.replay.active?'Restart replay':'Replay range'}</button>${state.replay.active?`<button id="replay-play" type="button">${state.replay.playing?'Pause':'Play'}</button><input id="replay-scrub" type="range" min="0" max="${Math.max(0,state.replay.events.length-1)}" value="${state.replay.index}"><strong id="replay-mode">REPLAY ${state.replay.index+1}/${state.replay.events.length}</strong><button id="replay-live" type="button">LIVE</button>`:'<strong id="replay-mode">LIVE</strong>'}</div><div id="timeline-rows">${timelineRows(rows)}</div>`;$('#timeline-filter').onchange=async e=>{const payload=await api(`/api/timeline?category=${encodeURIComponent(e.target.value)}&limit=500`);$('#timeline-rows').innerHTML=timelineRows((payload.events||[]).slice().reverse())};$('#replay-range').onclick=()=>loadReplayRange();const play=$('#replay-play');if(play)play.onclick=()=>replayPlayPause();const scrub=$('#replay-scrub');if(scrub)scrub.oninput=e=>{state.replay.index=Number(e.target.value);renderReplayControls()};const live=$('#replay-live');if(live)live.onclick=()=>exitReplay()}else if(kind==='settings'){const cfg=d.config||{};$('#utility-title').textContent='Floor Settings';content.innerHTML=settingsView(cfg,d)} }
function timelineRows(rows){return rows.map(e=>`<div class="trace-row"><span class="row-meta">${esc(String(e.timestamp||'').slice(11,19))}<br>${esc(e.agent_id||e.source||'office')}</span><span><strong>${esc(e.kind)}</strong><br>${esc(e.summary||'')}</span></div>`).join('')||'<div class="empty-panel">No activity.</div>'}
function taskCard(r){const t=r.task;return `<div class="task-card"><strong>${esc(t.task_id)} · ${esc(t.goal)}</strong><span class="owner">${esc(t.owner)}</span><p>${esc(r.state)} · ${esc(t.risk)} risk</p></div>`}
function memoryCards(rows,q=''){const needle=q.toLowerCase();const filtered=rows.filter(m=>!needle||JSON.stringify(m).toLowerCase().includes(needle));return filtered.slice().reverse().map(m=>`<div class="utility-card"><h3>${esc(m.kind)} ${m.verified?'✓':''}</h3><pre>${esc(JSON.stringify(m.data,null,2))}</pre></div>`).join('')||'<div class="empty-panel">No matching memory.</div>'}
function settingsView(cfg,d){const profiles=cfg.model_profiles||{},routing=cfg.routing||{};return `<div class="utility-grid"><section class="utility-card settings-form"><h3>Project</h3><p>${esc(d.project_root)}</p><label>Objective<textarea id="setting-objective" rows="4">${esc(d.status?.objective||'')}</textarea></label><button id="save-objective">Save objective</button></section><section class="utility-card"><h3>Models</h3>${Object.entries(profiles).map(([k,v])=>`<p><strong>${esc(k)}</strong><br>${esc(v.model||'')}<br>${esc(v.endpoint||'')}</p>`).join('')||'<p>No model profile configured.</p>'}<p>${Object.entries(routing).map(([k,v])=>`<span class="tag">${esc(k)} → ${esc(v)}</span>`).join('')}</p></section><section class="utility-card"><h3>Evidence</h3><p>${(d.evidence||[]).length} artifacts captured</p>${(d.evidence||[]).slice(-6).reverse().map(e=>`<p>${esc(e.name)} · ${esc(e.run_id)}</p>`).join('')}</section><section class="utility-card"><h3>Delivery</h3><p>${(d.delivery||[]).length} artifacts</p>${(d.delivery||[]).map(f=>`<p>${esc(f.name)}</p>`).join('')||'<p>No delivery package yet.</p>'}<button id="deliver-now">Build delivery</button></section></div>`}
async function decideApproval(id,decision){try{await api(`/api/approvals/${encodeURIComponent(id)}/${decision}`,{method:'POST',body:'{}'});toast(`Approval ${decision}d`);await refresh(false);openUtility('approvals')}catch(e){toast(e.message,true)}}

$('#board-btn').onclick=()=>openUtility('board');$('#approvals-btn').onclick=()=>openUtility('approvals');$('#memory-btn').onclick=()=>openUtility('memory');$('#timeline-btn').onclick=()=>openUtility('timeline');$('#settings-btn').onclick=()=>openUtility('settings');
$('#utility-modal').addEventListener('click',e=>{if(e.target.id==='save-objective'){saveObjective()}if(e.target.id==='deliver-now'){startJob('deliver')}});
async function saveObjective(){const objective=$('#setting-objective').value.trim();if(!objective)return;try{await api('/api/objective',{method:'POST',body:json({objective})});toast('Objective updated');await refresh(false)}catch(e){toast(e.message,true)}}

async function startJob(kind,payload={}){try{const r=await api(`/api/${kind}`,{method:'POST',body:json(payload)});toast(`${kind} job ${r.job_id} started`);watchJob(r.job_id)}catch(e){toast(e.message,true)}}
async function watchJob(id){for(let i=0;i<3600;i++){await new Promise(r=>setTimeout(r,900));const j=await api('/api/jobs/'+encodeURIComponent(id));if(j.state!=='RUNNING'){toast(j.state==='PASS'?`${j.name} completed`:`${j.name} failed: ${j.error?.message||'unknown error'}`,j.state!=='PASS');await refresh(false);return}}}
$('#run-btn').onclick=()=>startJob('run',{mode:selectedRunMode(),objective:state.data?.status?.objective||''});$('#verify-btn').onclick=()=>startJob('verify');

function show(id){$('#'+id)?.classList.remove('hidden')}function hide(id){$('#'+id)?.classList.add('hidden')}
$$('[data-close]').forEach(b=>b.onclick=()=>hide(b.dataset.close));

const archivePattern=/\.(zip|tar|tgz|tar\.gz|tbz2|tar\.bz2|txz|tar\.xz)$/i;
function setIntakeProgress(text=''){const el=$('#intake-progress');if(!el)return;el.textContent=text;el.classList.toggle('hidden',!text)}
function setIntakeSummary(text){const el=$('#intake-source-summary');if(el)el.textContent=text||'No source selected yet.'}
function setIntakeMode(mode){state.intake.mode=mode;$$('[data-intake-mode]').forEach(b=>b.classList.toggle('active',b.dataset.intakeMode===mode));$$('.intake-source-panel').forEach(p=>p.classList.add('hidden'));$('#intake-source-panel-'+mode)?.classList.remove('hidden');$('#open-existing').classList.toggle('hidden',mode!=='folder');if(mode==='folder')setIntakeSummary($('#intake-path-input').value.trim()||'Choose, drop or enter a local folder/archive path.');if(mode==='files'&&!state.intake.uploadItems.length&&!state.intake.localFiles.length)setIntakeSummary('Choose files, an archive, or a browser folder.');if(mode==='paste')setIntakeSummary('Paste one or more named files.');if(mode==='git')setIntakeSummary('Enter an explicit Git repository URL.');if(mode==='new')setIntakeSummary('Start from the objective only; no source files required.')}
function resetIntakeForm(keepObjective=false){state.intake.uploadItems=[];state.intake.localFiles=[];$('#intake-path-input').value='';$('#intake-git-url').value='';$('#intake-git-name').value='';$('#intake-new-name').value='';$('#paste-project-name').value='';if(!keepObjective)$('#intake-objective').value='';$('#intake-files').value='';$('#intake-folder').value='';$('#paste-items').innerHTML=pasteItemMarkup();$('#onboarding-error').textContent='';setIntakeProgress('');setIntakeMode('folder')}
function openUniversalIntake(newFloor=false,prefill=''){state.intake.open=true;state.intake.newFloor=!!newFloor;$('#intake-kicker').textContent=newFloor?'NEW FLOOR':'OPEN A FLOOR';$('#intake-title').textContent=newFloor?'Open another project.':'Give the office a project.';$('#create-office').textContent=newFloor?'Create floor':'Create office';$('#intake-close').classList.toggle('hidden',!state.data?.initialized);show('onboarding');if(prefill){setIntakeMode('folder');$('#intake-path-input').value=prefill;setIntakeSummary(prefill)}}
function closeUniversalIntake(){if(!state.data?.initialized)return;state.intake.open=false;hide('onboarding');setIntakeProgress('')}
function pasteItemMarkup(path='',content=''){return `<div class="paste-item"><input class="paste-path" value="${esc(path)}" placeholder="filename, e.g. src/main.py (optional)" /><textarea class="paste-content" rows="5" placeholder="Paste code, text, requirements or configuration here">${esc(content)}</textarea><button class="remove-paste-file" type="button" title="Remove pasted file">×</button></div>`}
function addPasteItem(){$('#paste-items').insertAdjacentHTML('beforeend',pasteItemMarkup())}
function selectedUploadItems(files){return [...files].map(file=>({file,path:file.webkitRelativePath||file.name}))}
function setUploadItems(items,label=''){state.intake.uploadItems=items;state.intake.localFiles=[];setIntakeSummary(label||`${items.length} item${items.length===1?'':'s'} selected\n${items.slice(0,6).map(x=>x.path).join('\n')}${items.length>6?'\n…':''}`)}
async function walkDropEntry(entry,prefix=''){if(entry.isFile)return await new Promise((resolve,reject)=>entry.file(file=>resolve([{file,path:prefix+file.name}]),reject));if(!entry.isDirectory)return[];const reader=entry.createReader();const all=[];while(true){const batch=await new Promise((resolve,reject)=>reader.readEntries(resolve,reject));if(!batch.length)break;for(const child of batch)all.push(...await walkDropEntry(child,prefix+entry.name+'/'))}return all}
async function collectDroppedFiles(dt){const entries=[...(dt.items||[])].map(item=>item.webkitGetAsEntry?.()).filter(Boolean);if(entries.length){const out=[];for(const entry of entries)out.push(...await walkDropEntry(entry,''));return out}return selectedUploadItems(dt.files||[])}
function desktopBridge(){return window.engineeringOfficeDesktop||null}

$$('[data-intake-mode]').forEach(b=>b.onclick=()=>setIntakeMode(b.dataset.intakeMode));
$('#intake-close').onclick=()=>closeUniversalIntake();
$('#add-paste-file').onclick=()=>addPasteItem();
$('#paste-items').addEventListener('click',e=>{if(e.target.classList.contains('remove-paste-file')){const rows=$$('.paste-item');if(rows.length>1)e.target.closest('.paste-item').remove();else{e.target.closest('.paste-item').querySelector('.paste-path').value='';e.target.closest('.paste-item').querySelector('.paste-content').value=''}}});
$('#intake-path-input').oninput=e=>{if(state.intake.mode==='folder')setIntakeSummary(e.target.value.trim()||'Choose, drop or enter a local folder/archive path.')};

$('#choose-folder').onclick=async()=>{const bridge=desktopBridge();if(bridge?.chooseProjectFolder){const path=await bridge.chooseProjectFolder();if(path){$('#intake-path-input').value=path;setIntakeSummary(path)}}else{$('#intake-folder').click()}};
$('#choose-archive').onclick=async()=>{const bridge=desktopBridge();if(bridge?.chooseArchive){const path=await bridge.chooseArchive();if(path){$('#intake-path-input').value=path;setIntakeSummary(path)}}else{$('#intake-files').accept='.zip,.tar,.tgz,.tar.gz,.tbz2,.tar.bz2,.txz,.tar.xz';$('#intake-files').dataset.intent='archive';$('#intake-files').click()}};
$('#choose-files').onclick=async()=>{setIntakeMode('files');const bridge=desktopBridge();if(bridge?.chooseFiles){const paths=await bridge.chooseFiles();if(paths?.length){state.intake.localFiles=paths;state.intake.uploadItems=[];setIntakeSummary(`${paths.length} local file${paths.length===1?'':'s'} selected\n${paths.slice(0,6).join('\n')}`)}}else{$('#intake-files').accept='';$('#intake-files').dataset.intent='files';$('#intake-files').click()}};
$('#choose-upload-folder').onclick=()=>{$('#intake-folder').click()};
$('#intake-files').onchange=e=>{const items=selectedUploadItems(e.target.files);setIntakeMode('files');setUploadItems(items);if(e.target.dataset.intent==='archive'&&items.length===1)setIntakeSummary(`Archive selected: ${items[0].path} · ${items[0].file.size} bytes`)};
$('#intake-folder').onchange=e=>{const items=selectedUploadItems(e.target.files);setIntakeMode('files');setUploadItems(items,`${items.length} files selected from folder\n${items[0]?.path?.split('/')[0]||''}`)};

const dropZone=$('#intake-drop-zone');
['dragenter','dragover'].forEach(type=>dropZone.addEventListener(type,e=>{e.preventDefault();dropZone.classList.add('dragging')}));
['dragleave','drop'].forEach(type=>dropZone.addEventListener(type,e=>{e.preventDefault();dropZone.classList.remove('dragging')}));
dropZone.addEventListener('drop',async e=>{try{const items=await collectDroppedFiles(e.dataTransfer);if(!items.length)throw new Error('No files were available in that drop.');setIntakeMode('files');setUploadItems(items)}catch(err){$('#onboarding-error').textContent=err.message}});

async function uploadBrowserItems(items,objective){if(!items.length)throw new Error('Choose files, an archive, or a folder first.');const archive=items.length===1&&archivePattern.test(items[0].path);setIntakeProgress('Uploading');const created=await api('/api/intake/sessions',{method:'POST',body:json({name:items[0].path.split('/')[0],objective,...(archive?{mode:'archive'}:{mode:'files'})})});try{for(const item of items){await apiBinary(`/api/intake/sessions/${encodeURIComponent(created.session_id)}/file?path=${encodeURIComponent(item.path)}`,item.file)}setIntakeProgress(archive?'Extracting':'Validating');const result=await api(`/api/intake/sessions/${encodeURIComponent(created.session_id)}/commit`,{method:'POST',body:'{}'});setIntakeProgress('Detecting project root');return result}catch(err){try{await api(`/api/intake/sessions/${encodeURIComponent(created.session_id)}`,{method:'DELETE'})}catch{}throw err}}

async function normalizeIntake(objective){const mode=state.intake.mode;setIntakeProgress('Validating');if(mode==='folder'){if(state.intake.uploadItems.length)return uploadBrowserItems(state.intake.uploadItems,objective);const path=$('#intake-path-input').value.trim();if(!path)throw new Error('Choose a folder/archive or enter a local path.');if(archivePattern.test(path))setIntakeProgress('Extracting');const result=await api('/api/intake/path',{method:'POST',body:json({path,objective})});setIntakeProgress('Detecting project root');return result}if(mode==='files'){if(state.intake.localFiles.length){return await api('/api/intake/files',{method:'POST',body:json({paths:state.intake.localFiles,objective,name:''})})}return uploadBrowserItems(state.intake.uploadItems,objective)}if(mode==='paste'){const items=$$('.paste-item').map(row=>({path:row.querySelector('.paste-path').value.trim(),content:row.querySelector('.paste-content').value})).filter(item=>item.path||item.content);return api('/api/intake/paste',{method:'POST',body:json({name:$('#paste-project-name').value.trim(),objective,items})})}if(mode==='git'){const url=$('#intake-git-url').value.trim();if(!url)throw new Error('Enter a Git repository URL.');return api('/api/intake/git',{method:'POST',body:json({url,name:$('#intake-git-name').value.trim(),objective})})}if(mode==='new'){return api('/api/intake/new',{method:'POST',body:json({name:$('#intake-new-name').value.trim(),objective})})}throw new Error('Choose a project source.')}

$('#onboarding-form').onsubmit=async e=>{e.preventDefault();const objective=$('#intake-objective').value.trim();$('#onboarding-error').textContent='';try{if(state.intake.mode==='new'&&!objective)throw new Error('A new project needs an objective.');const normalized=await normalizeIntake(objective);setIntakeProgress('Opening floor');if(!normalized.initialized){if(!objective)throw new Error('This is a new Office floor. Describe the objective before staffing the team.');setIntakeProgress('Staffing team');await api('/api/start',{method:'POST',body:json({objective})})}state.selected='Office Director';state.detail=null;state.intake.open=false;hide('onboarding');setIntakeProgress('');toast('Floor opened and team staffed');await refresh(false)}catch(err){$('#onboarding-error').textContent=err.message;setIntakeProgress('')}};
$('#open-existing').onclick=async()=>{const path=$('#intake-path-input').value.trim();$('#onboarding-error').textContent='';if(!path)return $('#onboarding-error').textContent='Enter or choose an existing Office project folder.';try{setIntakeProgress('Opening floor');const d=await api('/api/project',{method:'POST',body:json({path})});if(!d.initialized)throw new Error('No existing .office state found. Add an objective and choose Create office.');state.selected='Office Director';state.detail=null;state.intake.open=false;hide('onboarding');setIntakeProgress('');await refresh(false)}catch(err){$('#onboarding-error').textContent=err.message;setIntakeProgress('')}};

$('#add-agent-form').onsubmit=async e=>{e.preventDefault();const expertise=$('#add-agent-expertise').value.trim();$('#add-agent-error').textContent='';try{const a=await api('/api/add-agent',{method:'POST',body:json({expertise})});hide('add-agent-modal');$('#add-agent-expertise').value='';toast(`${a.name} joined the floor`);await refresh(false);await selectAgent(a.name)}catch(err){$('#add-agent-error').textContent=err.message}};

document.addEventListener('click',e=>{if(!e.target.closest('#floor-switcher')&&!e.target.closest('#floor-menu')){$('#floor-menu').classList.add('hidden');$('#floor-switcher').setAttribute('aria-expanded','false')}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.intake.open&&state.data?.initialized)closeUniversalIntake();$$('.modal-backdrop').forEach(el=>{if(el.id!=='onboarding')el.classList.add('hidden')});$('#floor-menu').classList.add('hidden')}});
resetIntakeForm(true);refresh(false);state.timer=setInterval(()=>refresh(true),2200);
